'use strict';

/**
 * POST /api/cart  -- blueprint function "cart-add".
 * Monolith source: bookstore/routes/cart.js:68-94 (+ utils/dynamodb.js, config.js).
 *
 * Response headers (SI-01 / analysis_report global_middleware[0], server.js:29-31
