 * they become { statusCode: err.status || 500, body: { error, stack } }. A body that
 * cannot be parsed is one of those errors with status 400 (SI-04), which is why the
 * malformed-JSON arm answers 400 + { error, stack }.
 */

const { DynamoDBClient } = require('@aws-sdk/client-dynamodb');
const { DynamoDBDocumentClient, PutCommand } = require('@aws-sdk/lib-dynamodb');

// SI-13: table name comes from the Lambda environment; the client is built once in
// the module scope so a warm container reuses its connections.
const docClient = DynamoDBDocumentClient.from(new DynamoDBClient({}));
const cartTable = process.env.CART_TABLE;

const RESPONSE_HEADERS = {
  'Content-Type': 'application/json',
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Credentials': 'true',
};

function respond(statusCode, payload) {
  return { statusCode, headers: RESPONSE_HEADERS, body: JSON.stringify(payload) };
}

function respondError(err) {
  return respond(err && err.status ? err.status : 500, {
    error: (err && err.message) || 'Internal Server Error',
    stack: err && err.stack,
  });
}

// --- request body, the way body-parser gave it to Express (SI-04) -------------

const FIRST_CHAR_REGEXP = /^[\x20\x09\x0a\x0d]*([^\x20\x09\x0a\x0d])/;
const JSON_SYNTAX_CHAR = '#';
const JSON_SYNTAX_REGEXP = /#+/g;

function headerValue(event, name) {
  const wanted = String(name).toLowerCase();
  const headers = event.headers || {};
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === wanted) return String(headers[key]);
  }
  const multi = event.multiValueHeaders || {};
  for (const key of Object.keys(multi)) {
    if (key.toLowerCase() === wanted) {
      const values = multi[key];
      return String(Array.isArray(values) ? values[values.length - 1] : values);
    }
  }
  return '';
}

// body-parser's strict JSON errors keep the runtime's own message: a placeholder run
// stands where the offending slice of the body will be shown.
function normalizeJsonSyntaxError(error, obj) {
  for (const key of Object.getOwnPropertyNames(error)) {
    if (key !== 'stack' && key !== 'message') delete error[key];
  }
  error.stack = obj.stack.replace(error.message, obj.message);
  error.message = obj.message;
  return error;
}

function createStrictSyntaxError(str, char) {
  const index = str.indexOf(char);
  let partial = '';
  if (index !== -1) {
    partial = str.substring(0, index) + JSON_SYNTAX_CHAR;
    for (let i = index + 1; i < str.length; i++) partial += JSON_SYNTAX_CHAR;
  }
  try {
    JSON.parse(partial);
    throw new SyntaxError('strict violation');
  } catch (e) {
    return normalizeJsonSyntaxError(e, {
      message: e.message.replace(JSON_SYNTAX_REGEXP, (placeholder) => str.substring(index, index + placeholder.length)),
      stack: e.stack
    });
  }
}

function parseJsonBody(text) {
  const match = FIRST_CHAR_REGEXP.exec(text);
  const first = match ? match[1] : undefined;
  if (first !== '{' && first !== '[') {
    throw createStrictSyntaxError(text, first);
  }
  try {
    return JSON.parse(text);
  } catch (error) {
    throw normalizeJsonSyntaxError(error, { message: error.message, stack: error.stack });
  }
}

// Every form value arrives as a string and is stored as one (SI-06); no coercion here.
function parseFormBody(text) {
  const out = {};
  if (!text) return out;
  for (const pair of text.split('&')) {
    if (!pair) continue;
    const eq = pair.indexOf('=');
    const rawKey = eq === -1 ? pair : pair.slice(0, eq);
    const rawValue = eq === -1 ? '' : pair.slice(eq + 1);
    out[decodeComponent(rawKey)] = decodeComponent(rawValue);
  }
  return out;
}

function decodeComponent(value) {
  try {
    return decodeURIComponent(value.replace(/\+/g, ' '));
  } catch (error) {
    return value;
  }
}

function parseBody(event) {
  let raw = event.body;
  if (raw != null && event.isBase64Encoded) raw = Buffer.from(String(raw), 'base64').toString('utf8');
  if (raw == null) return {};
  const text = String(raw);
  const contentType = headerValue(event, 'content-type');
  if (/application\/json/i.test(contentType)) {
    try {
      return parseJsonBody(text);
    } catch (error) {
      error.status = 400;
      throw error;
    }
  }
  if (/application\/x-www-form-urlencoded/i.test(contentType)) return parseFormBody(text);
  return {};
}

/**
 * The owner of the cart. The gateway's Cognito authorizer has already validated the
 * token (SI-11), and REST puts its claims here; x-customer-id is not an identity
 * source any more and is never read (SI-12 / J4-3). A customerId in the body is
 * ignored (BR-CART-ADD-2).
 */
function customerIdOf(event) {
  return event.requestContext.authorizer.claims.sub;
}

exports.handler = async function (event, context) {
  let body;
  try {
    body = parseBody(event);
  } catch (error) {
    console.error('Error in POST /cart:', error);
    return respondError(error);
  }

  try {
    const { bookId, quantity, price } = body;

    // Truthiness only (BR-CART-ADD-1): 0, '' and null all count as missing.
    if (!bookId || !quantity || !price) {
      return respond(400, {
        error: 'Missing required fields: bookId, quantity, price'
      });
    }

    const params = {
      TableName: cartTable,
      Item: {
        customerId: customerIdOf(event),
        bookId: bookId,
        quantity: quantity,
        price: price
      }
    };

    // Whole-row PutItem, no read-modify-write, no ConditionExpression (BR-CART-ADD-3/5,
    // SI-23); values are stored exactly as sent (SI-06).
    await docClient.send(new PutCommand(params));
    return respond(200, { message: 'Item added to cart successfully' });
  } catch (error) {
    console.error('Error in POST /cart:', error);
    return respondError(error);
  }
};

