// the module scope so a warm container reuses its connections.
const docClient = DynamoDBDocumentClient.from(new DynamoDBClient({}));
const bestsellersTable = process.env.BESTSELLERS_TABLE;
const idempotencyTable = process.env.IDEMPOTENCY_TABLE;

const MARKER_PREFIX = 'bestsellers-update';
const MARKER_TTL_SECONDS = 7 * 24 * 60 * 60;
const TRANSIENT_ATTEMPTS = 3;
const TRANSIENT_BACKOFF_MS = 100;

// Errors that retrying can clear (the SDK's own retry has already tried, so a second
// bounded pass here is what "don't swallow a conflict" asks for).
const TRANSIENT_ERRORS = new Set([
  'ThrottlingException',
  'ProvisionedThroughputExceededException',
  'TransactionInProgressException',
  'TransactionConflictException',
  'InternalServerError',
  'ServiceUnavailable',
  'RequestTimeout',
  'RequestThrottled',
]);

