  if (!err) return false;
  if (err.name === 'ConditionalCheckFailedException') return false;
  if (TRANSIENT_ERRORS.has(err.name)) return true;
  // Transport failures reach us as TypeError/TimeoutError/socket errors.
  return err.$metadata && err.$metadata.httpStatusCode >= 500;
}

