  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * (a) Claim this (orderId, index). True when this delivery is the first one that got
 * here, false when an earlier delivery already applied the element.
 */
async function claimElement(orderId, index, bookId) {
  const params = {
    TableName: idempotencyTable,
    Item: {
      pk: `${MARKER_PREFIX}#${orderId}#${index}`,
      orderId: orderId,
      bookId: bookId,
      createdAt: Date.now(),
      expiresAt: Math.floor(Date.now() / 1000) + MARKER_TTL_SECONDS
