 * (b) The counter update, utils/bestsellers.js:17-26 verbatim: ADD on the key, no
 * ConditionExpression, so the first sale creates the row.
 */
async function addSalesCount(bookId, quantity) {
  const params = {
    TableName: bestsellersTable,
    Key: { bookId: bookId },
    UpdateExpression: 'ADD salesCount :qty',
    ExpressionAttributeValues: {
      ':qty': quantity
    }
  };

  await docClient.send(new UpdateCommand(params));
}

async function withTransientRetry(operation, what) {
  let lastError = null;
  for (let attempt = 1; attempt <= TRANSIENT_ATTEMPTS; attempt++) {
    try {
      return await operation();
    } catch (error) {
      lastError = error;
      if (!isTransient(error)) throw error;
      if (attempt < TRANSIENT_ATTEMPTS) {
        console.warn(`Retrying ${what} (attempt ${attempt}):`, error.message);
        await sleep(TRANSIENT_BACKOFF_MS * attempt);
      }
    }
  }
  throw lastError;
}

exports.handler = async function (event, context) {
  const batchItemFailures = [];

  for (const record of event.Records || []) {
    let payload;
    try {
      payload = JSON.parse(record.body);
    } catch (error) {
      // A message we cannot read will not become readable by redelivery (SI-10).
      console.error('Failed to parse bestseller update message:', error);
      continue;
    }

    const orderId = payload && payload.orderId;
    const books = payload && payload.books;
    if (!orderId || !Array.isArray(books)) {
      console.error('Bestseller update message has no orderId or no books array; skipping');
      continue;
    }

    // Sequential, in the message's own order, like the for..of in utils/bestsellers.js:48.
    for (let index = 0; index < books.length; index++) {
      const book = books[index];
      const bookId = book && book.bookId;
      const quantity = book && book.quantity;

      try {
        const claimed = await withTransientRetry(
          () => claimElement(orderId, index, bookId),
          `idempotency claim for ${orderId}[${index}]`
        );
        if (!claimed) {
          console.log(`Bestseller update already applied: ${orderId}[${index}]`);
          continue;
        }

        await withTransientRetry(() => addSalesCount(bookId, quantity), `ADD salesCount for ${bookId}`);
        console.log(`Updated bestseller: bookId=${bookId}, quantity=${quantity}`);
      } catch (error) {
        if (isTransient(error)) {
          // Still failing after the bounded retries: hand it back so SQS redelivers.
          console.error('Transient failure updating bestseller:', error);
          const identifier = { itemIdentifier: record.messageId };
          if (!batchItemFailures.some((f) => f.itemIdentifier === identifier.itemIdentifier)) {
            batchItemFailures.push(identifier);
          }
        } else {
          // Permanent, e.g. ValidationException on a string quantity: the monolith's
          // updateBestSeller caught it and returned false (BR-ORD-CRT-9/14).
          console.error('Failed to update bestseller:', error);
        }
      }
    }
  }

  // ReportBatchItemFailures: only the listed messages are redelivered; an empty list
  // means the whole batch is done.
  return { batchItemFailures };
};

