function respond(statusCode, payload) {
  return { statusCode, headers: RESPONSE_HEADERS, body: JSON.stringify(payload) };
}

function respondError(err) {
  return respond(err && err.status ? err.status : 500, {
    error: (err && err.message) || 'Internal Server Error',
    stack: err && err.stack,
  });
}

/**
 * Express's req.query shape (SI-05 / D-12): one value per key is a string, the same
 * key sent twice is an array. REST payload 1.0 hands both forms over, so rebuild the
 * array here instead of taking the last value -- GET /api/books?category=a&category=b
 * must reach DynamoDB as an array and fail the way the monolith fails.
 */
function queryParam(event, name) {
  const multi = event.multiValueQueryStringParameters;
  if (multi && Object.prototype.hasOwnProperty.call(multi, name)) {
    const values = multi[name];
    if (Array.isArray(values)) return values.length === 1 ? values[0] : values;
    return values;
  }
  const single = event.queryStringParameters;
  return single ? single[name] : undefined;
}

